
package dev.yinghuang.legacyforgebridge.repair322;
import com.google.gson.*;import org.objectweb.asm.tree.*;import org.objectweb.asm.tree.analysis.*;import java.util.*;import java.io.*;import static org.objectweb.asm.Opcodes.*;import static dev.yinghuang.legacyforgebridge.repair322.CoreVisualPass322.*;
/** Generic registered block-item renderer scaling and icon-grid inventory cropping. */
public final class HeldPass323 {
 static AbstractInsnNode root(MethodNode m,Frame<SourceValue>[] fs,SourceValue v,int depth){if(depth>24)throw new IllegalArgumentException("alias depth");AbstractInsnNode n=ArmorCompiler323.origin(v);int i=m.instructions.indexOf(n);if(n instanceof VarInsnNode load){if(load.getOpcode()>=ILOAD&&load.getOpcode()<=ALOAD)return root(m,fs,fs[i].getLocal(load.var),depth+1);if(load.getOpcode()>=ISTORE&&load.getOpcode()<=ASTORE)return root(m,fs,fs[i].getStack(fs[i].getStackSize()-1),depth+1);}if(n.getOpcode()==DUP||n.getOpcode()==CHECKCAST)return root(m,fs,fs[i].getStack(fs[i].getStackSize()-1),depth+1);return n;}
 static Map<String,String> bindings(FeaturePass323 f){Map<String,String> out=new TreeMap<>();for(ClassNode c:f.p.classes.values())for(MethodNode m:c.methods){Frame<SourceValue>[] fs;try{fs=new Analyzer<>(new SourceInterpreter()).analyze(c.name,m);}catch(Exception e){continue;}for(int i=0;i<m.instructions.size();i++)if(m.instructions.get(i) instanceof MethodInsnNode call&&call.owner.equals("net/minecraftforge/client/MinecraftForgeClient")&&call.name.equals("registerItemRenderer")){try{Frame<SourceValue> fr=fs[i];int size=fr.getStackSize();AbstractInsnNode item=root(m,fs,fr.getStack(size-2),0),renderer=root(m,fs,fr.getStack(size-1),0);if(!(renderer instanceof TypeInsnNode alloc)||alloc.getOpcode()!=NEW)continue;String id=null;if(item instanceof MethodInsnNode q&&q.name.equals("func_150898_a")){int at=m.instructions.indexOf(item);AbstractInsnNode block=root(m,fs,fs[at].getStack(fs[at].getStackSize()-1),0);if(block instanceof FieldInsnNode b)id=f.fieldIds.get(b.owner+"."+b.name);}else if(item instanceof FieldInsnNode b)id=f.fieldIds.get(b.owner+"."+b.name);if(id!=null)out.put(id,alloc.desc);}catch(Exception ignored){}}}return out;}
 static JsonObject sourceScale(ClassNode c)throws Exception {MethodNode m=c.methods.stream().filter(x->x.name.equals("renderItem")).findFirst().orElseThrow();Frame<SourceValue>[] fs=new Analyzer<>(new SourceInterpreter()).analyze(c.name,m);List<List<Float>> scales=new ArrayList<>();Set<String> contexts=new HashSet<>();JsonArray other=new JsonArray();for(int i=0;i<m.instructions.size();i++){AbstractInsnNode n=m.instructions.get(i);if(n instanceof FieldInsnNode q&&q.owner.equals("net/minecraftforge/client/IItemRenderer$ItemRenderType"))contexts.add(q.name);if(n instanceof MethodInsnNode q&&q.owner.equals("org/lwjgl/opengl/GL11")){int top=fs[i].getStackSize();if(q.name.equals("glScalef")){List<Float> v=new ArrayList<>();for(int j=3;j>0;j--)v.add(((Number)ArmorCompiler323.constant(new SourceValue(1,root(m,fs,fs[i].getStack(top-j),0)))).floatValue());scales.add(v);}else if(q.name.equals("glTranslatef")||q.name.equals("glRotatef"))other.add(q.name);}}
  if(scales.isEmpty()||new HashSet<>(scales).size()!=1)throw new IllegalArgumentException("nonuniform renderer scale requires matrix contract");for(float n:scales.getFirst())if(!Float.isFinite(n)||n<=0||n>16)throw new IllegalArgumentException("scale range");JsonObject proof=new JsonObject();proof.add("scale",G.toJsonTree(scales.getFirst()));proof.add("contexts",G.toJsonTree(contexts));proof.add("untranslatedLegacyMatrixOperations",other);return proof;
 }
 public static void apply(FeaturePass323 f)throws Exception {CoreVisualPass322 p=f.p;JsonObject grids=obj(p.read("legacyforgebridge/visual-programs322.json"),"grids"),held=new JsonObject();JsonObject base;try(InputStream in=HeldPass323.class.getResourceAsStream("/assets/minecraft/models/block/block.json")){if(in==null)throw new IllegalArgumentException("native default display model unavailable");base=JsonParser.parseReader(new InputStreamReader(in)).getAsJsonObject().getAsJsonObject("display");}
  for(var binding:bindings(f).entrySet()){String id=binding.getKey(),ns=id.split(":")[0],path=id.split(":",2)[1];try{JsonObject proof=sourceScale(p.classes.get(binding.getValue()));String modelName="lfb_held323/"+path;JsonObject model=new JsonObject();boolean blockItem=false;for(var e:p.content.getAsJsonArray("blocks"))if(e.getAsJsonObject().get("id").getAsString().equals(id))blockItem=true;model.addProperty("parent",ns+(blockItem?":block/":":item/")+path);JsonObject display=base.deepCopy();JsonArray scale=proof.getAsJsonArray("scale");Set<String> contexts=new HashSet<>();for(var c:proof.getAsJsonArray("contexts"))contexts.add(c.getAsString());for(var entry:display.entrySet()){String context=entry.getKey();boolean active=context.startsWith("firstperson")?contexts.contains("EQUIPPED_FIRST_PERSON"):context.startsWith("thirdperson")?contexts.contains("EQUIPPED"):context.equals("ground")&&contexts.contains("ENTITY");if(!active)continue;JsonObject t=entry.getValue().getAsJsonObject();JsonArray old=t.has("scale")?t.getAsJsonArray("scale"):G.toJsonTree(new float[]{1,1,1}).getAsJsonArray();JsonArray v=new JsonArray();for(int i=0;i<3;i++)v.add(old.get(i).getAsFloat()*scale.get(i).getAsFloat());t.add("scale",v);}model.add("display",display);
   if(grids.has(id)){int size=grids.getAsJsonObject(id).get("size").getAsInt();JsonObject block=p.read("assets/"+ns+"/models/block/"+path+".json");if(block.has("textures"))model.add("textures",block.get("textures"));JsonArray elems=new JsonArray();JsonObject e=new JsonObject(),faces=new JsonObject();e.add("from",G.toJsonTree(new int[]{0,0,0}));e.add("to",G.toJsonTree(new int[]{16,16,16}));String[] directions={"down","up","north","south","west","east"};for(String d:directions){JsonObject face=new JsonObject();String tex=block.getAsJsonObject("textures").has(d)?"#"+d:block.getAsJsonObject("textures").has("all")?"#all":"#"+(d.equals("up")||d.equals("down")?"end":"side");face.addProperty("texture",tex);face.addProperty("tintindex",0);face.add("uv",G.toJsonTree(new float[]{0,0,16f/size,16f/size}));faces.add(d,face);}e.add("faces",faces);elems.add(e);model.add("elements",elems);proof.addProperty("inventoryIconGrid",size);}
   p.write("assets/"+ns+"/models/item/"+modelName+".json",model);JsonObject def=new JsonObject(),leaf=new JsonObject();leaf.addProperty("type","minecraft:model");leaf.addProperty("model",ns+":item/"+modelName);JsonObject old=p.read("assets/"+ns+"/items/"+path+".json");if(old.has("model")&&old.getAsJsonObject("model").has("tints"))leaf.add("tints",old.getAsJsonObject("model").get("tints"));def.add("model",leaf);p.write("assets/"+ns+"/items/"+path+".json",def);obj(obj(p.iconBook,"items"),id).addProperty("0",id);proof.addProperty("sourceRenderer",binding.getValue());held.add(id,proof);System.out.println("HELD_SCALE "+id+"="+scale);
  }catch(Exception e){f.fail(id,"held-transform",e);}}f.manifest.add("held",held);
 }
}
